contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient test balance");

        uint beforeContractBalance = address(c).balance;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint afterContractBalance = address(c).balance;

        assert(afterContractBalance >= beforeContractBalance + amount);
    }

    receive() external payable {}
}

